class Bond : public Instrument {
public:
    Bond(double faceValue, double yield) : faceValue_(faceValue), yield_(yield) {}
    double price() const override {
        return faceValue_ / (1.0 + yield_);   // simplified single-period discount
    }
private:
    double faceValue_;
    double yield_;
};

struct Trade {
    int id;
    double price;
    long quantity;

    bool operator==(const Trade& rhs) const {
        return id == rhs.id && price == rhs.price && quantity == rhs.quantity;
    }
};
